1. import type { CartLine } from "./product.ts";
2. 
3. /**
4.  * TaxCalculator is a seam consumers (and tests) substitute to compute tax.
5.  * Implementations must be pure and deterministic for a given input.
6.  */
7. export interface TaxCalculator {
8.   /**
9.    * @param taxableCents Subtotal after any discounts.
10.    * @param region  ISO-3166-1 alpha-2 country code (and optionally a sub-division), e.g. "US",
11.    *                "US-CA", "FR". Implementations decide how granular they go.
12.    * @returns Tax amount in cents as a non-negative integer. Rounded down to nearest cent.
13.    */
14.   computeTaxCents(taxableCents: number, region: string): number;
15. }
16. 
17. export class NoTaxCalculator implements TaxCalculator {
18.   computeTaxCents(_taxableCents: number, _region: string): number {
19.     return 0;
20.   }
21. }
22. 
23. /**
24.  * Looks up a flat tax rate per region. Unknown regions fall back to a default
25.  * rate (default 0). Rates are expressed as decimal fractions (e.g. 0.0875 for
26.  * 8.75%). The result is rounded down to the nearest cent.
27.  */
28. export class RegionalTaxCalculator implements TaxCalculator {
29.   constructor(
30.     private readonly rates: Readonly<Record<string, number>>,
31.     private readonly defaultRate: number = 0,
32.   ) {
33.     if (!Number.isFinite(defaultRate) || defaultRate < 0 || defaultRate > 1) {
34.       throw new RangeError(
35.         `defaultRate must be between 0 and 1 (got ${defaultRate})`,
36.       );
37.     }
38.     for (const [region, rate] of Object.entries(rates)) {
39.       if (!Number.isFinite(rate) || rate < 0 || rate > 1) {
40.         throw new RangeError(
41.           `rate for ${region} must be between 0 and 1 (got ${rate})`,
42.         );
43.       }
44.     }
45.   }
46. 
47.   computeTaxCents(taxableCents: number, region: string): number {
48.     if (taxableCents <= 0) return 0;
49.     const rate = this.rates[region] ?? this.defaultRate;
50.     return Math.floor(taxableCents * rate);
51.   }
52. }
53. 
54. /**
55.  * Async seam for callers that resolve rates from a remote service.
56.  *
57.  * Cart.checkout() uses this seam when configured; tests typically substitute
58.  * a mock returning a resolved promise (e.g. `vi.fn().mockResolvedValue(...)`).
59.  */
60. export interface AsyncTaxRateProvider {
61.   getRate(region: string): Promise<number>;
62. }
63. 
64. /** Convenience adapter: drives a synchronous TaxCalculator off a provider's rate. */
65. export class AsyncTaxCalculator {
66.   constructor(private readonly provider: AsyncTaxRateProvider) {}
67. 
68.   async computeTaxCents(taxableCents: number, region: string): Promise<number> {
69.     if (taxableCents <= 0) return 0;
70.     const rate = await this.provider.getRate(region);
71.     if (!Number.isFinite(rate) || rate < 0 || rate > 1) {
72.       throw new RangeError(`tax rate for ${region} must be between 0 and 1 (got ${rate})`);
73.     }
74.     return Math.floor(taxableCents * rate);
75.   }
76. }
77. 
78. /** Helper for tests / callers that need to compute taxable weight from lines. */
79. export function totalLineWeightGrams(lines: readonly CartLine[]): number {
80.   let total = 0;
81.   for (const line of lines) {
