      expect(calc.computeShippingCents(lines, 100)).toBe(500); // exactly 2000g
    });

    it("uses last bracket cost as overflow when no overflowCostCents set", () => {
      const lines = [makeLine("a", 100, 1, 5000)];
      expect(calc.computeShippingCents(lines, 100)).toBe(500); // over all brackets
    });

    it("uses explicit overflowCostCents when set", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 200 },
          { upToGrams: 1000, costCents: 300 },
        ],
        800,
      );
      const lines = [makeLine("a", 100, 1, 1500)];
      expect(calcWithOverflow.computeShippingCents(lines, 100)).toBe(800);
    });

    it("sums weight across multiple lines and quantities", () => {
      const lines = [
        makeLine("a", 100, 2, 200), // 400g
        makeLine("b", 200, 1, 300), // 300g
      ];
      // total weight = 700g → ≤1000g bracket = 300
      expect(calc.computeShippingCents(lines, 300)).toBe(300);
    });
  });
});

