      cart.add(gadget, 2);
      expect(cart.itemCount).toBe(3);
    });

    it("rejects non-positive quantity", () => {
      expect(() => cart.add(widget, 0)).toThrow(RangeError);
      expect(() => cart.add(widget, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      expect(() => cart.add(widget, 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const bad: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
      expect(() => cart.add(bad, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      cart.add(widget, 1);
      expect(cart.remove("w1")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      cart.add(widget, 5);
      cart.updateQuantity("w1", 3);
      expect(cart.itemCount).toBe(3);
    });

    it("removes product when quantity set to 0", () => {
      cart.add(widget, 5);
      cart.updateQuantity("w1", 0);
      expect(cart.itemCount).toBe(0);
      expect(cart.remove("w1")).toBe(false); // confirms it's gone
    });

    it("throws for unknown product id", () => {
      expect(() => cart.updateQuantity("unknown", 5)).toThrow(
        "Product unknown is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      cart.add(widget, 1);
      expect(() => cart.updateQuantity("w1", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      cart.add(widget, 1);
      expect(() => cart.updateQuantity("w1", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      cart.add(widget, 2);
      cart.add(gadget, 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });

    it("is idempotent on empty cart", () => {
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that cannot mutate internal state", () => {
      cart.add(widget, 2);
      const snap = cart.snapshot();
      snap[0]!.quantity = 999;
      snap[0]!.product.unitPriceCents = 0;
      expect(cart.itemCount).toBe(2);
      expect(cart.totals().subtotalCents).toBe(2000);
    });
  });
});

describe("Cart – totals (pricing pipeline)", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(widget, 2); // 1000 * 2 = 2000
    cart.add(gadget, 1); // 2000 * 1 = 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
    expect(totals.totalCents).toBe(4000); // no discount/tax/shipping
  });

  it("returns zero totals for empty cart", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("applies discount → tax on discounted subtotal → shipping", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };

    const cart = new Cart({ discountPolicy, taxCalculator, shippingCalculator, region: "US" });
    cart.add(widget, 2); // subtotal 2000

    const totals = cart.totals();

    // Discount called with subtotal
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(2000);
    expect(totals.discountCents).toBe(200);

    // Tax called with discounted subtotal (2000 - 200 = 1800)
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(1800, "US");
    expect(totals.taxCents).toBe(80);

    // Shipping called with lines and discounted subtotal
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      1800,
    );
    expect(totals.shippingCents).toBe(500);

    // total = discountedSubtotal + tax + shipping = 1800 + 80 + 500 = 2380
    expect(totals.totalCents).toBe(2380);
  });

  it("clamps discount to [0, subtotal]", () => {
    // Discount returns more than subtotal
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(widget, 1); // subtotal 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000); // clamped to subtotal
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negDiscount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy: negDiscount });
    cart.add(widget, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const negTax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(widget, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negShipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: negShipping });
    cart.add(widget, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("uses default region US when not specified", () => {
    const taxCalc: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(50),
    };
    const cart = new Cart({ taxCalculator: taxCalc });
    cart.add(widget, 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });

  it("uses custom region", () => {
    const taxCalc: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(50),
    };
    const cart = new Cart({ taxCalculator: taxCalc, region: "FR" });
    cart.add(widget, 1);
    cart.totals();
    expect(taxCalc.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });
});

