describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 5.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 500.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 300 },
      { upToGrams: 500, costCents: 200 },   // out of order to test sorting
      { upToGrams: 2000, costCents: 500 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 for items with zero weight", () => {
      const lines = [makeLine("a", 100, 2)]; // no weightGrams
      expect(calc.computeShippingCents(lines, 200)).toBe(0);
    });

    it("selects correct bracket for weight within first bracket", () => {
      const lines = [makeLine("a", 100, 1, 400)];
      expect(calc.computeShippingCents(lines, 100)).toBe(200); // ≤500g bracket
    });

    it("selects correct bracket at exact boundary", () => {
      const lines = [makeLine("a", 100, 1, 500)];
      expect(calc.computeShippingCents(lines, 100)).toBe(200); // exactly 500g
    });

    it("selects next bracket when weight exceeds boundary", () => {
      const lines = [makeLine("a", 100, 1, 501)];
      expect(calc.computeShippingCents(lines, 100)).toBe(300); // ≤1000g bracket
    });

    it("selects highest bracket at its boundary", () => {
      const lines = [makeLine("a", 100, 1, 2000)];
      expect(calc.computeShippingCents(lines, 100)).toBe(500); // exactly 2000g
    });

    it("uses last bracket cost as overflow when no overflowCostCents set", () => {
      const lines = [makeLine("a", 100, 1, 5000)];
      expect(calc.computeShippingCents(lines, 100)).toBe(500); // over all brackets
    });

    it("uses explicit overflowCostCents when set", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [
          { upToGrams: 500, costCents: 200 },
          { upToGrams: 1000, costCents: 300 },
        ],
        800,
      );
      const lines = [makeLine("a", 100, 1, 1500)];
      expect(calcWithOverflow.computeShippingCents(lines, 100)).toBe(800);
    });

    it("sums weight across multiple lines and quantities", () => {
      const lines = [
        makeLine("a", 100, 2, 200), // 400g
        makeLine("b", 200, 1, 300), // 300g
      ];
      // total weight = 700g → ≤1000g bracket = 300
      expect(calc.computeShippingCents(lines, 300)).toBe(300);
    });
  });
});

